create table if not exists public.guest_campaigns (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, name text not null check (length(trim(name)) between 1 and 160), channel text not null check (channel in ('email','sms','whatsapp')), status text not null default 'draft' check (status in ('draft','scheduled','sent','paused')), audience_filter jsonb not null default '{}'::jsonb, sent_at timestamptz, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.guest_campaign_recipients (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, campaign_id uuid not null references public.guest_campaigns(id) on delete cascade, guest_id uuid not null references public.guests(id) on delete cascade, consented boolean not null default false, status text not null default 'pending' check (status in ('pending','sent','delivered','failed','opted_out')), attributed_revenue_cents integer not null default 0 check (attributed_revenue_cents >= 0), sent_at timestamptz, converted_at timestamptz, unique(campaign_id, guest_id));
create index if not exists guest_campaigns_tenant_idx on public.guest_campaigns(tenant_id, created_at desc); create index if not exists guest_campaign_recipients_campaign_idx on public.guest_campaign_recipients(tenant_id, campaign_id);
alter table public.guest_campaigns enable row level security; alter table public.guest_campaigns force row level security; alter table public.guest_campaign_recipients enable row level security; alter table public.guest_campaign_recipients force row level security;
create policy guest_campaigns_read on public.guest_campaigns for select using (public.is_tenant_member(tenant_id)); create policy guest_campaigns_write on public.guest_campaigns for all using (public.has_tenant_role(tenant_id, array['owner','manager']::public.tenant_role[])) with check (public.has_tenant_role(tenant_id, array['owner','manager']::public.tenant_role[]));
create policy guest_campaign_recipients_read on public.guest_campaign_recipients for select using (public.is_tenant_member(tenant_id)); create policy guest_campaign_recipients_write on public.guest_campaign_recipients for all using (public.has_tenant_role(tenant_id, array['owner','manager']::public.tenant_role[])) with check (public.has_tenant_role(tenant_id, array['owner','manager']::public.tenant_role[]));
